//! Temporary storage policy. Entry points accept only validated team-workspace roots.
use std::{collections::{BTreeMap,BTreeSet},fs,path::{Path,PathBuf,Component},sync::Mutex,time::{SystemTime,UNIX_EPOCH}};
use serde::{Serialize,Deserialize};use serde_json::{Value,json};use sha2::{Digest,Sha256};
use crate::{Shared,core::Res};
pub const TTL:u64=24*60*60;
static LOCK:Mutex<()>=Mutex::new(());
pub fn now()->u64{SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default().as_secs()}
#[derive(Clone)]pub struct TempRoot(PathBuf);
impl TempRoot{
 pub fn new(team:&Path,uid:&str)->Res<Self>{uuid::Uuid::parse_str(uid).map_err(|_|"INVALID_ACCOUNT")?;let parent=team.join("workspaces").canonicalize().map_err(|_|"WORKSPACE_UNAVAILABLE")?;let root=parent.join(uid).canonicalize().map_err(|_|"WORKSPACE_UNAVAILABLE")?;if root.parent()!=Some(parent.as_path()){return Err("RETENTION_BOUNDARY_REJECTED".into())}Ok(Self(root))}
 pub fn path(&self)->&Path{&self.0}
}
#[derive(Default,Serialize,Deserialize)]struct Lease{fingerprint:String,expires:u64}
#[derive(Default,Serialize,Deserialize)]struct Output{#[serde(default)]revision:String,refs:BTreeSet<String>,expires:u64,#[serde(default)]saved:bool,#[serde(default)]sha256:Option<String>}
#[derive(Default,Serialize,Deserialize)]struct Ledger{started:u64,assets:BTreeMap<String,Lease>,outputs:BTreeMap<String,Output>,#[serde(default)]aux:BTreeMap<String,BTreeSet<String>>}
fn load(root:&TempRoot,time:u64)->Res<Ledger>{match fs::read(root.0.join("retention.json")){Ok(b)=>serde_json::from_slice(&b).map_err(|_|"RETENTION_STATE_INVALID".into()),Err(e)if e.kind()==std::io::ErrorKind::NotFound=>Ok(Ledger{started:time,..Default::default()}),Err(_)=>Err("RETENTION_STATE_UNAVAILABLE".into())}}
fn atomic(path:&Path,v:&impl Serialize)->Res<()>{use std::io::Write;let mut f=tempfile::NamedTempFile::new_in(path.parent().ok_or("INVALID_PATH")?).map_err(|e|e.to_string())?;f.write_all(&serde_json::to_vec_pretty(v).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;f.as_file().sync_all().map_err(|e|e.to_string())?;f.persist(path).map_err(|e|e.to_string())?;Ok(())}
fn save(root:&TempRoot,l:&Ledger)->Res<()>{atomic(&root.0.join("retention.json"),l)}
fn relative(root:&TempRoot,path:&Path)->Option<String>{
 if path.components().any(|c|matches!(c,Component::ParentDir|Component::CurDir)){return None}
 let full=if path.is_absolute(){path.to_path_buf()}else{root.0.join(path)};let mut head=full.clone();let mut tail=vec![];
 while !head.exists(){tail.push(head.file_name()?.to_os_string());if !head.pop(){return None}}
 let mut canonical=head.canonicalize().ok()?;for part in tail.into_iter().rev(){canonical.push(part)}
 let rel=canonical.strip_prefix(&root.0).ok()?;let parts=rel.components().map(|c|match c{Component::Normal(s)=>s.to_str().filter(|s|!s.contains([':', '\\'])&&!s.ends_with(['.',' '])),_=>None}).collect::<Option<Vec<_>>>()?;
 if parts.is_empty(){return None}Some(parts.join("/"))
}

fn modified(path:&Path)->u64{fs::metadata(path).and_then(|m|m.modified()).ok().and_then(|t|t.duration_since(UNIX_EPOCH).ok()).map(|t|t.as_secs()).unwrap_or(0)}
fn key(pid:&str,aid:&str)->Option<String>{uuid::Uuid::parse_str(pid).ok()?;uuid::Uuid::parse_str(aid).ok()?;Some(format!("{pid}/{aid}"))}
fn refs(pid:&str,ids:&Value)->BTreeSet<String>{ids.as_array().map(|a|a.iter().filter_map(|v|key(pid,v.as_str()?)).collect()).unwrap_or_default()}
fn outputs_in(root:&TempRoot,path:&Path,out:&mut Vec<String>){if let Ok(entries)=fs::read_dir(path){for e in entries.flatten(){let Ok(kind)=e.file_type() else{continue};if kind.is_symlink(){continue}let Ok(real)=e.path().canonicalize() else{continue};if !real.starts_with(&root.0){continue}if kind.is_dir(){outputs_in(root,&e.path(),out)}else if let Some(rel)=relative(root,&e.path()){out.push(rel)}}}}
fn register(root:&TempRoot,l:&mut Ledger,path:&str,owners:BTreeSet<String>,time:u64){
 let Some(rel)=relative(root,Path::new(path)) else{return};if !rel.starts_with("exports/"){return}
 let file=root.0.join(&rel);let revision=fs::metadata(&file).ok().and_then(|m|m.modified().ok().and_then(|t|t.duration_since(UNIX_EPOCH).ok()).map(|t|format!("{}:{}",m.len(),t.as_nanos())));
 let expires=modified(&file).max(l.started).min(time).saturating_add(TTL);let o=l.outputs.entry(rel).or_insert_with(||Output{expires,..Default::default()});
 if let Some(revision)=revision{if !o.revision.is_empty()&&o.revision!=revision{o.saved=false;o.sha256=None;o.expires=time+TTL;o.refs.clear();}o.revision=revision;}
 o.refs.extend(owners);
}

fn documents(root:&TempRoot,folder:&str)->Res<Vec<(PathBuf,Value)>>{let mut out=vec![];let dir=root.0.join(folder);if !dir.exists(){return Ok(out)}for e in fs::read_dir(dir).map_err(|e|e.to_string())?{let e=e.map_err(|e|e.to_string())?;if e.file_type().map_err(|e|e.to_string())?.is_symlink(){return Err("RETENTION_BOUNDARY_REJECTED".into())}if !e.file_type().map_err(|e|e.to_string())?.is_dir(){continue}let p=e.path().join(if folder=="hybrid-jobs"{"job.json"}else{"project.json"});if p.exists(){let real=p.canonicalize().map_err(|e|e.to_string())?;if !real.starts_with(&root.0){return Err("RETENTION_BOUNDARY_REJECTED".into())}let v=serde_json::from_slice(&fs::read(&p).map_err(|e|e.to_string())?).map_err(|_|"RETENTION_DOCUMENT_INVALID")?;out.push((p,v))}}Ok(out)}
fn scan_new_tasks(root:&TempRoot,l:&mut Ledger,time:u64,active:&mut BTreeSet<String>)->Res<()>{for folder in ["operation-jobs","new-product-jobs"]{let dir=root.0.join(folder);if !dir.is_dir(){continue}for entry in fs::read_dir(&dir).map_err(|e|e.to_string())?{let entry=entry.map_err(|e|e.to_string())?;if entry.file_type().map_err(|e|e.to_string())?.is_symlink(){return Err("RETENTION_BOUNDARY_REJECTED".into())}if !entry.file_type().map_err(|e|e.to_string())?.is_file(){continue}let path=entry.path();let extension=path.extension().and_then(|s|s.to_str()).unwrap_or("");if !matches!(extension,"json"|"planning"){continue}let Some(id)=path.file_stem().and_then(|s|s.to_str()).filter(|s|uuid::Uuid::parse_str(s).is_ok())else{continue};if extension=="planning"&&(dir.join(format!("{id}.cancel")).exists()||entry.metadata().and_then(|m|m.modified()).ok().and_then(|t|t.elapsed().ok()).is_some_and(|age|age.as_secs()>=120)){continue}let bytes=fs::read(&path).map_err(|e|e.to_string())?;let value:Value=match serde_json::from_slice(&bytes){Ok(value)=>value,Err(_)if extension=="planning"=>continue,Err(_)=>return Err("RETENTION_DOCUMENT_INVALID".into())};let pid=value["projectId"].as_str().ok_or("RETENTION_DOCUMENT_INVALID")?;let state=value["state"].as_str().or(value["status"].as_str()).unwrap_or("planning");let live=!matches!(state,"done"|"completed"|"partial"|"failed"|"cancelled");let mut owners=refs(pid,&value["context"]["resolvedTarget"]["ids"]);owners.extend(refs(pid,&value["assetIds"]));if let Some(items)=value["items"].as_array(){for item in items{let aid=item["id"].as_str().ok_or("RETENTION_DOCUMENT_INVALID")?;owners.insert(key(pid,aid).ok_or("RETENTION_DOCUMENT_INVALID")?);for suffix in ["png","remote"]{let rel=format!("operation-jobs/{id}-{aid}.{suffix}");if root.0.join(&rel).is_file(){l.aux.insert(rel,owners.clone());}}}}if let Some(tasks)=value["tasks"].as_array(){for task in tasks{if let Some(aid)=task["result"]["assetId"].as_str(){owners.insert(key(pid,aid).ok_or("RETENTION_DOCUMENT_INVALID")?);}}}let completed=if folder=="operation-jobs"{value["updatedAt"].as_u64().unwrap_or(0)/1000}else{value["updatedAt"].as_u64().unwrap_or(0)};if live{active.extend(owners.clone());}else if completed>0&&completed<=time{for owner in &owners{if let Some(lease)=l.assets.get_mut(owner){lease.expires=lease.expires.max(completed.saturating_add(TTL));}}}
 if folder=="operation-jobs"&&extension=="json"{let outputs=dir.join(format!("{id}.outputs"));if outputs.is_file(){let values:Value=serde_json::from_slice(&fs::read(outputs).map_err(|e|e.to_string())?).map_err(|_|"RETENTION_DOCUMENT_INVALID")?;for output in values.as_object().ok_or("RETENTION_DOCUMENT_INVALID")?.values(){if output["status"]!="ok"{continue}let aid=output["assetId"].as_str().ok_or("RETENTION_DOCUMENT_INVALID")?;let owner=key(pid,aid).ok_or("RETENTION_DOCUMENT_INVALID")?;let format=output["format"].as_str().filter(|f|["webp","png","jpeg"].contains(f)).ok_or("RETENTION_DOCUMENT_INVALID")?;let ext=if format=="jpeg"{"jpg"}else{format};let payload=root.0.join("exports").join(id).join(format!("{aid}.{ext}"));register(root,l,&payload.to_string_lossy(),BTreeSet::from([owner]),time);if !live&&completed>0&&completed<=time{if let Some(relative)=relative(root,&payload){if let Some(output)=l.outputs.get_mut(&relative){output.expires=output.expires.max(completed.saturating_add(TTL));}}}}}}
 } }Ok(())}
fn scan(root:&TempRoot,l:&mut Ledger,time:u64)->Res<(Vec<(PathBuf,Value)>,Vec<(PathBuf,Value)>,BTreeSet<String>)>{
 let mut projects=documents(root,"projects")?;projects.extend(documents(root,"deleted-projects")?);let jobs=documents(root,"hybrid-jobs")?;let mut active=BTreeSet::new();
 for (_,p) in &projects{let pid=p["id"].as_str().ok_or("INVALID_PROJECT")?;for a in p["assets"].as_array().ok_or("INVALID_PROJECT")?{let Some(k)=key(pid,a["id"].as_str().unwrap_or("")) else{return Err("INVALID_ASSET".into())};let fingerprint=json!([a["sha256"],a["generatedBase"],a["versions"]]).to_string();match l.assets.get_mut(&k){Some(v)if v.fingerprint!=fingerprint=>{v.fingerprint=fingerprint;v.expires=time+TTL},None=>{l.assets.insert(k,Lease{fingerprint,expires:time+TTL});},_=>{}}}}
 for (_,j) in &jobs{let pid=j["projectId"].as_str().unwrap_or("");let live=!crate::hybrid::terminal(j["state"].as_str().unwrap_or(""));for item in j["items"].as_array().ok_or("INVALID_JOB")?{let Some(k)=key(pid,item["assetId"].as_str().unwrap_or("")) else{return Err("INVALID_JOB".into())};if live&&!matches!(item["stage"].as_str().unwrap_or(""),"done"|"failed"|"cancelled"){active.insert(k.clone());}if let Some(path)=item["exported"].as_str(){register(root,l,path,BTreeSet::from([k]),time);}}}
 scan_new_tasks(root,l,time,&mut active)?;
 for (_,job)in &jobs{if let Some(items)=job["items"].as_array(){for item in items{if let Some(path)=item["exported"].as_str(){if let Some(rel)=relative(root,Path::new(path)).filter(|rel|rel.starts_with("pipeline-staging/")){if let Some(owner)=key(job["projectId"].as_str().unwrap_or(""),item["assetId"].as_str().unwrap_or("")){l.aux.insert(rel,BTreeSet::from([owner]));}}}}}}
 let mut files=vec![];outputs_in(root,&root.0.join("exports"),&mut files);for path in files{register(root,l,&path,BTreeSet::new(),time)}
 Ok((projects,jobs,active))
}
fn record_values(root:&TempRoot,l:&mut Ledger,v:&Value,pid:&str,default:&BTreeSet<String>,time:u64){match v{Value::Array(a)=>for x in a{record_values(root,l,x,pid,default,time)},Value::Object(o)=>{let owners=o.get("assetId").and_then(Value::as_str).and_then(|a|key(pid,a)).map(|k|BTreeSet::from([k])).unwrap_or_else(||default.clone());if let Some(path)=o.get("path").and_then(Value::as_str){register(root,l,path,owners.clone(),time)}for x in o.values(){if x.is_array()||x.is_object(){record_values(root,l,x,pid,&owners,time)}}},_=>{}}}
pub fn record(root:&TempRoot,shared:&Shared,command:&str,args:&Value,result:&Value,time:u64)->Res<()>{let _g=LOCK.lock().map_err(|_|"RETENTION_LOCK")?;let store=crate::locked(shared)?;if store.root.canonicalize().ok().as_ref()!=Some(&root.0){return Err("RETENTION_BOUNDARY_REJECTED".into())}let mut l=load(root,time)?;scan(root,&mut l,time)?;let mut pid=args["projectId"].as_str().unwrap_or("").to_string();let mut owners=refs(&pid,&args["ids"]);if let Some(k)=args["assetId"].as_str().and_then(|a|key(&pid,a)){owners.insert(k);}
 if command=="assistant_apply"{if let Some(id)=args["sampleId"].as_str(){if uuid::Uuid::parse_str(id).is_ok(){if let Ok(b)=fs::read(root.0.join("assistant-samples").join(format!("{id}.json"))){if let Ok(v)=serde_json::from_slice::<Value>(&b){pid=v["projectId"].as_str().unwrap_or("").into();owners=refs(&pid,&v["ids"]);}}}}}
 record_values(root,&mut l,result,&pid,&owners,time);
 if let Some(path)=result["savedPath"].as_str(){if let Some(rel)=relative(root,Path::new(path)){if rel.starts_with("generated/"){l.aux.insert(rel.clone(),owners.clone());if let Some(id)=Path::new(&rel).file_stem().and_then(|x|x.to_str()).and_then(|s|s.strip_prefix("generated-")){if uuid::Uuid::parse_str(id).is_ok(){l.aux.insert(format!("generated/{id}-usage.json"),owners.clone());}}}}}
 if let Some(id)=result["sampleId"].as_str(){if uuid::Uuid::parse_str(id).is_ok(){l.aux.insert(format!("assistant-samples/{id}.json"),owners);}}
 save(root,&l)
}
// Every deletion resolves a path inside this account, including every recursive child.
fn remove(root:&TempRoot,rel:&str)->Res<()>{let clean=relative(root,Path::new(rel)).ok_or("RETENTION_BOUNDARY_REJECTED")?;let p=root.0.join(clean);if !p.exists(){return Ok(())}let meta=fs::symlink_metadata(&p).map_err(|e|e.to_string())?;if meta.file_type().is_symlink(){return Err("RETENTION_BOUNDARY_REJECTED".into())}let real=p.canonicalize().map_err(|e|e.to_string())?;if real==root.0||!real.starts_with(&root.0){return Err("RETENTION_BOUNDARY_REJECTED".into())}if meta.is_dir(){for e in fs::read_dir(&p).map_err(|e|e.to_string())?{let e=e.map_err(|e|e.to_string())?;remove(root,&relative(root,&e.path()).ok_or("RETENTION_BOUNDARY_REJECTED")?)?;}fs::remove_dir(p).map_err(|e|e.to_string())}else{fs::remove_file(p).map_err(|e|e.to_string())}}
#[derive(Default,Serialize)]#[serde(rename_all="camelCase")]pub struct Summary{pub removed_files:usize,pub removed_assets:usize,pub deferred_assets:usize}
fn sweep_locked(root:&TempRoot,shared:&Shared,l:&mut Ledger,time:u64)->Res<Summary>{let _store=crate::locked(shared)?;let (mut projects,mut jobs,active)=scan(root,l,time)?;let mut report=Summary::default();
 // Journal saved acknowledgements before deleting payloads, so retries cannot resurrect them.
 save(root,l)?;
 for (rel,o) in &l.outputs{if o.saved||o.expires<=time&&!o.refs.iter().any(|owner|active.contains(owner)){if root.0.join(rel).exists(){remove(root,rel)?;report.removed_files+=1;}}}
 let mut cleared=BTreeSet::new();for (path,p) in &mut projects{let pid=p["id"].as_str().unwrap_or("").to_string();let mut keep=vec![];for a in p["assets"].as_array().ok_or("INVALID_PROJECT")?{let k=key(&pid,a["id"].as_str().unwrap_or("")).ok_or("INVALID_ASSET")?;let related=l.outputs.values().filter(|o|o.refs.contains(&k)).collect::<Vec<_>>();let pending=related.iter().any(|o|!o.saved&&o.expires>time);let saved=!related.is_empty()&&related.iter().all(|o|o.saved);let expired=l.assets.get(&k).is_some_and(|a|a.expires<=time);if active.contains(&k)||pending||(!saved&&!expired){if related.iter().any(|o|o.saved){report.deferred_assets+=1;}keep.push(a.clone());continue}
   let base=path.parent().unwrap();let mut media=vec![];if let Some(s)=a["original"].as_str(){media.push(base.join(s));}if let Some(vs)=a["versions"].as_array(){for v in vs{if let Some(f)=v["file"].as_str(){media.push(base.join(f));}}}media.push(base.join(format!("thumbs/{}.png",a["id"].as_str().unwrap())));
   for f in media{remove(root,&relative(root,&f).ok_or("RETENTION_BOUNDARY_REJECTED")?)?;}
   cleared.insert(k);report.removed_assets+=1;
  }if keep.len()!=p["assets"].as_array().unwrap().len(){p["assets"]=json!(keep);p["updatedAt"]=json!(time);atomic(path,p)?;}}
 for (path,j) in &mut jobs{if !crate::hybrid::terminal(j["state"].as_str().unwrap_or("")){continue}let pid=j["projectId"].as_str().unwrap_or("").to_string();let mut changed=false;let mut all_clean=true;for item in j["items"].as_array_mut().ok_or("INVALID_JOB")?{let k=key(&pid,item["assetId"].as_str().unwrap_or("")).ok_or("INVALID_JOB")?;let rel=item["exported"].as_str().and_then(|p|relative(root,Path::new(p)));if let Some(rel)=rel{if l.outputs.get(&rel).is_some_and(|o|o.saved||o.expires<=time){let saved=l.outputs[&rel].saved;item["exported"]=Value::Null;item["retentionStatus"]=json!(if saved{"saved_locally"}else{"expired"});changed=true;}}
  if !cleared.contains(&k)&&l.assets.contains_key(&k){all_clean=false;}}
  if all_clean{for e in fs::read_dir(path.parent().unwrap()).map_err(|e|e.to_string())?{let e=e.map_err(|e|e.to_string())?;if !["job.json","notified","cancel.request"].iter().any(|n|e.file_name()==*n){remove(root,&relative(root,&e.path()).ok_or("RETENTION_BOUNDARY_REJECTED")?)?;}}}if changed{atomic(path,j)?;}}
 for k in &cleared{l.assets.remove(k);}
 let mut aux_remove=vec![];for (rel,owners) in &l.aux{if !owners.is_empty()&&owners.iter().all(|k|!l.assets.contains_key(k))||modified(&root.0.join(rel)).max(l.started)+TTL<=time{if !owners.iter().any(|k|active.contains(k)){remove(root,rel)?;aux_remove.push(rel.clone());}}}for rel in aux_remove{l.aux.remove(&rel);}
 // Remove orphan image payloads left by interrupted writes, without touching live references.
 if active.is_empty(){let mut referenced=BTreeSet::new();for (path,p) in &projects{let base=path.parent().unwrap();for a in p["assets"].as_array().ok_or("INVALID_PROJECT")?{if let Some(f)=a["original"].as_str(){if let Some(r)=relative(root,&base.join(f)){referenced.insert(r);}}if let Some(vs)=a["versions"].as_array(){for v in vs{if let Some(f)=v["file"].as_str(){if let Some(r)=relative(root,&base.join(f)){referenced.insert(r);}}}}if let Some(id)=a["id"].as_str(){if let Some(r)=relative(root,&base.join(format!("thumbs/{id}.png"))){referenced.insert(r);}}}}
  for folder in ["projects","deleted-projects"]{let mut payloads=vec![];outputs_in(root,&root.0.join(folder),&mut payloads);for rel in payloads{let image=Path::new(&rel).extension().and_then(|x|x.to_str()).is_some_and(|s|["png","jpg","jpeg","webp"].contains(&s.to_ascii_lowercase().as_str()));if image&&!referenced.contains(&rel)&&modified(&root.0.join(&rel)).max(l.started)+TTL<=time{remove(root,&rel)?;report.removed_files+=1;}}}
 }
 // Legacy untracked generated/sampling payloads receive the same 24-hour migration grace.
 if active.is_empty(){for folder in ["generated","assistant-samples","uploads"]{let mut paths=vec![];outputs_in(root,&root.0.join(folder),&mut paths);for rel in paths{if modified(&root.0.join(&rel)).max(l.started)+TTL<=time{remove(root,&rel)?;}}}}
 save(root,l)?;Ok(report)
}
pub fn sweep(root:&TempRoot,shared:&Shared,time:u64)->Res<Summary>{let _g=LOCK.lock().map_err(|_|"RETENTION_LOCK")?;let mut l=load(root,time)?;sweep_locked(root,shared,&mut l,time)}
pub fn acknowledge(root:&TempRoot,shared:&Shared,path:&Path,sha:&str,bytes:u64,time:u64)->Res<Summary>{let _g=LOCK.lock().map_err(|_|"RETENTION_LOCK")?;let rel=relative(root,path).filter(|p|p.starts_with("exports/")).ok_or("RETENTION_BOUNDARY_REJECTED")?;let mut l=load(root,time)?;
 {let _store=crate::locked(shared)?;scan(root,&mut l,time)?;}
 let existing=l.outputs.get(&rel).ok_or("FILE_NOT_FOUND")?;if existing.saved&&existing.sha256.as_deref()==Some(sha){return sweep_locked(root,shared,&mut l,time)}
 let actual=path.canonicalize().map_err(|_|"FILE_NOT_FOUND")?;if !actual.starts_with(&root.0){return Err("RETENTION_BOUNDARY_REJECTED".into())}let data=fs::read(actual).map_err(|_|"FILE_NOT_FOUND")?;if data.len() as u64!=bytes||format!("{:x}",Sha256::digest(&data))!=sha{return Err("SAVED_FILE_MISMATCH".into())}let o=l.outputs.get_mut(&rel).unwrap();o.saved=true;o.sha256=Some(sha.into());save(root,&l)?;sweep_locked(root,shared,&mut l,time)
}
pub fn file_status(root:&TempRoot,shared:&Shared,time:u64)->Res<BTreeMap<String,Value>>{let _g=LOCK.lock().map_err(|_|"RETENTION_LOCK")?;let _store=crate::locked(shared)?;let mut l=load(root,time)?;scan(root,&mut l,time)?;save(root,&l)?;Ok(l.outputs.iter().map(|(p,o)|(p.trim_start_matches("exports/").to_string(),json!({"expiresAt":o.expires,"saved":o.saved}))).collect())}
#[cfg(test)]mod tests{
 #[test]fn unsaved_standard_output_survives_active_work_and_expires_24_hours_after_completion(){let(_temp,root,s,pid,aid,original)=setup();let id=uuid::Uuid::new_v4().to_string();let jobs=root.0.join("operation-jobs");let payload=root.0.join("exports").join(&id);fs::create_dir_all(&jobs).unwrap();fs::create_dir_all(&payload).unwrap();let file=payload.join(format!("{aid}.webp"));fs::write(&file,b"verified-delivery-fixture").unwrap();atomic(&jobs.join(format!("{id}.json")),&json!({"projectId":pid,"state":"waiting","updatedAt":1000000,"items":[{"id":aid}]})).unwrap();atomic(&jobs.join(format!("{id}.outputs")),&json!({(aid.clone()):{"assetId":aid,"name":"result.webp","format":"webp","status":"ok"}})).unwrap();sweep(&root,&s,1000).unwrap();sweep(&root,&s,1000+TTL+1).unwrap();assert!(file.exists());assert!(original.exists());let completed=1000+TTL+2;atomic(&jobs.join(format!("{id}.json")),&json!({"projectId":pid,"state":"done","updatedAt":completed*1000,"items":[{"id":aid}]})).unwrap();sweep(&root,&s,completed+TTL-1).unwrap();assert!(file.exists());assert!(original.exists());sweep(&root,&s,completed+TTL+1).unwrap();assert!(!file.exists());assert!(!original.exists());}
 #[test]fn new_operation_and_new_product_jobs_protect_sources_and_extend_completed_retention(){let(_temp,root,s,pid,aid,original)=setup();sweep(&root,&s,1000).unwrap();let operations=root.0.join("operation-jobs");let products=root.0.join("new-product-jobs");fs::create_dir_all(&operations).unwrap();fs::create_dir_all(&products).unwrap();let op=uuid::Uuid::new_v4().to_string();let np=uuid::Uuid::new_v4().to_string();atomic(&operations.join(format!("{op}.json")),&json!({"projectId":pid,"state":"waiting","updatedAt":1000000,"items":[{"id":aid}]})).unwrap();atomic(&products.join(format!("{np}.json")),&json!({"projectId":pid,"status":"attention","updatedAt":1000,"context":{"resolvedTarget":{"ids":[aid]}}})).unwrap();sweep(&root,&s,1000+TTL+1).unwrap();assert!(original.exists());fs::remove_file(operations.join(format!("{op}.json"))).unwrap();sweep(&root,&s,1000+TTL+2).unwrap();assert!(original.exists());let finished=1000+TTL+3;atomic(&products.join(format!("{np}.json")),&json!({"projectId":pid,"status":"done","updatedAt":finished,"context":{"resolvedTarget":{"ids":[aid]}}})).unwrap();sweep(&root,&s,finished+TTL-1).unwrap();assert!(original.exists());sweep(&root,&s,finished+TTL+1).unwrap();assert!(!original.exists());}
 #[test]fn planning_context_protects_source_before_an_execution_job_exists(){let(_temp,root,s,pid,aid,original)=setup();sweep(&root,&s,1000).unwrap();let operations=root.0.join("operation-jobs");fs::create_dir_all(&operations).unwrap();let marker=operations.join(format!("{}.planning",uuid::Uuid::new_v4()));atomic(&marker,&json!({"projectId":pid,"assetIds":[aid],"state":"planning"})).unwrap();sweep(&root,&s,1000+TTL+1).unwrap();assert!(original.exists());fs::remove_file(marker).unwrap();sweep(&root,&s,1000+TTL+2).unwrap();assert!(!original.exists());}
 use super::*;use crate::{AppState,Store};use std::sync::{Arc,atomic::{AtomicBool,AtomicU64}};use image::{DynamicImage,RgbImage,Rgb};
 fn setup()->(tempfile::TempDir,TempRoot,Shared,String,String,PathBuf){let temp=tempfile::tempdir().unwrap();let team=temp.path().join("team");let uid=uuid::Uuid::new_v4().to_string();let ws=team.join("workspaces").join(&uid);let store=Store::open(ws.clone(),"test").unwrap();fs::create_dir_all(ws.join("exports")).unwrap();let p=store.create("temporary".into()).unwrap();let source=temp.path().join("original.png");DynamicImage::ImageRgb8(RgbImage::from_pixel(8,8,Rgb([80,100,120]))).save(&source).unwrap();let report=store.import(&p.id,vec![source.to_string_lossy().into()],&AtomicBool::new(false),|_,_|{}).unwrap();let aid=report.project.assets[0].id.clone();let original=ws.join("projects").join(&p.id).join(&report.project.assets[0].original);let shared=Arc::new(AppState{store:Mutex::new(store),cancel:AtomicBool::new(false),local_job:Mutex::new(()),preview_epoch:AtomicU64::new(0)});let root=TempRoot::new(&team,&uid).unwrap();(temp,root,shared,p.id,aid,original)}
 fn export(root:&TempRoot,s:&Shared,pid:&str,aid:&str,format:&str,time:u64)->PathBuf{let preset=crate::core::ExportPreset{format:format.into(),width:8,height:8,fit:"pad".into(),quality:90,max_bytes:100000,output_dir:root.0.join("exports").to_string_lossy().into(),background:[255,255,255]};let result=crate::locked(s).unwrap().export(pid,vec![aid.into()],preset,&AtomicBool::new(false),|_,_|{}).unwrap();let path=PathBuf::from(result[0].path.clone().unwrap());record(root,s,"export_run",&json!({"projectId":pid,"ids":[aid]}),&serde_json::to_value(result).unwrap(),time).unwrap();path}
 fn ack(root:&TempRoot,s:&Shared,p:&Path,time:u64)->Summary{let bytes=fs::read(p).unwrap();acknowledge(root,s,p,&format!("{:x}",Sha256::digest(&bytes)),bytes.len() as u64,time).unwrap()}
 #[test]fn verified_save_removes_only_its_team_original_and_result(){let (temp,root,s,pid,aid,original)=setup();let owner=temp.path().join("owner-private");fs::create_dir(&owner).unwrap();fs::write(owner.join("original.png"),b"owner sentinel").unwrap();let out=export(&root,&s,&pid,&aid,"webp",1000);let bytes=fs::read(&out).unwrap();let sha=format!("{:x}",Sha256::digest(&bytes));let result=ack(&root,&s,&out,1001);assert_eq!(result.removed_assets,1);assert!(!original.exists());assert!(!out.exists());assert!(crate::locked(&s).unwrap().load(&pid).unwrap().assets.is_empty());assert_eq!(fs::read(owner.join("original.png")).unwrap(),b"owner sentinel");assert!(acknowledge(&root,&s,&out,&sha,bytes.len() as u64,1002).is_ok());}
 #[test]fn hash_mismatch_never_cleans(){let (_temp,root,s,pid,aid,original)=setup();let out=export(&root,&s,&pid,&aid,"webp",1000);assert!(acknowledge(&root,&s,&out,&"0".repeat(64),1,1001).is_err());assert!(original.exists()&&out.exists());}
 #[test]fn remaining_output_keeps_original_until_both_saved(){let (_temp,root,s,pid,aid,original)=setup();let first=export(&root,&s,&pid,&aid,"webp",1000);let second=export(&root,&s,&pid,&aid,"png",1001);let a=ack(&root,&s,&first,1002);assert_eq!(a.deferred_assets,1);assert!(original.exists()&&second.exists());assert!(!first.exists());ack(&root,&s,&second,1003);assert!(!original.exists()&&!second.exists());}
 #[test]fn ttl_is_24_hours_and_migration_does_not_delete_immediately(){let (_temp,root,s,pid,aid,original)=setup();let out=export(&root,&s,&pid,&aid,"webp",1000);sweep(&root,&s,1000+TTL-1).unwrap();assert!(original.exists()&&out.exists());sweep(&root,&s,1000+TTL+1).unwrap();assert!(!original.exists()&&!out.exists());}
 #[test]fn active_work_keeps_original_then_cleans_intermediates(){let (_temp,root,s,pid,aid,original)=setup();let out=export(&root,&s,&pid,&aid,"webp",1000);let job=root.0.join("hybrid-jobs").join(uuid::Uuid::new_v4().to_string());fs::create_dir_all(&job).unwrap();let mut value=json!({"projectId":pid,"state":"waiting","items":[{"assetId":aid,"stage":"submitted","exported":out}]});atomic(&job.join("job.json"),&value).unwrap();fs::write(job.join("response.json"),b"private encoded image").unwrap();let result=ack(&root,&s,&out,1001);assert!(result.deferred_assets>0);assert!(original.exists());value["state"]=json!("completed");value["items"][0]["stage"]=json!("done");atomic(&job.join("job.json"),&value).unwrap();sweep(&root,&s,1002).unwrap();assert!(!original.exists());assert!(!job.join("response.json").exists());let job:Value=serde_json::from_slice(&fs::read(job.join("job.json")).unwrap()).unwrap();assert_eq!(job["items"][0]["retentionStatus"],"saved_locally");}
 #[test]fn owner_and_parent_paths_cannot_enter_cleanup(){let (temp,root,s,pid,aid,_)=setup();assert!(TempRoot::new(temp.path(),"owner-private").is_err());assert!(relative(&root,Path::new("../accounts.json")).is_none());let outside=temp.path().join("owner-file.png");fs::write(&outside,b"keep").unwrap();assert!(acknowledge(&root,&s,&outside,&"0".repeat(64),4,1000).is_err());assert!(outside.exists());let _=export(&root,&s,&pid,&aid,"webp",1000);}
 #[test]fn exporting_again_to_a_cleaned_filename_requires_a_new_save(){let (_temp,root,s,pid,aid,original)=setup();let first=export(&root,&s,&pid,&aid,"webp",1000);let other=export(&root,&s,&pid,&aid,"png",1000);ack(&root,&s,&first,1001);assert!(original.exists());std::thread::sleep(std::time::Duration::from_millis(10));let new=export(&root,&s,&pid,&aid,"webp",1002);assert_eq!(new,first);let statuses=file_status(&root,&s,1003).unwrap();assert_eq!(statuses.values().filter(|v|v["saved"]==false).count(),2);ack(&root,&s,&other,1004);assert!(original.exists()&&new.exists());ack(&root,&s,&new,1005);assert!(!original.exists());}

}
